using System.Text;
using System.Text.Json;
using FluentAssertions;
using SranDesktop.Infrastructure.Documents;
using SranDesktop.Infrastructure.Office;
using UglyToad.PdfPig.Fonts.Standard14Fonts;
using UglyToad.PdfPig.Writer;
using Xunit;

namespace SranDesktop.Tests.Documents;

/// <summary>
/// Desktop D: local document text extraction. Every fixture here is a REAL
/// file written to disk by the same libraries a user's Office/Acrobat would
/// produce — no hand-rolled byte arrays, no mocks of the parsers. The Office
/// fixtures are generated by the app's own Local*PlanExecutors, which makes
/// these round-trip tests: what SRAN Desktop writes, SRAN Desktop can read.
/// </summary>
public sealed class DocumentTextExtractorTests : IDisposable
{
    private readonly string _dir;

    public DocumentTextExtractorTests()
    {
        _dir = Path.Combine(Path.GetTempPath(), $"sran-docs-{Guid.NewGuid():N}");
        Directory.CreateDirectory(_dir);
    }

    public void Dispose()
    {
        try { Directory.Delete(_dir, recursive: true); } catch (IOException) { }
    }

    private static JsonElement Plan(string json)
    {
        using var doc = JsonDocument.Parse(json);
        return doc.RootElement.Clone();
    }

    /// <summary>Writes a real PDF with a text layer, one line per page.</summary>
    private string WritePdf(string name, params string[] pageLines)
    {
        var builder = new PdfDocumentBuilder();
        var font = builder.AddStandard14Font(Standard14Font.Helvetica);
        foreach (var line in pageLines)
        {
            var page = builder.AddPage(595, 842); // A4 points
            page.AddText(line, 12, new UglyToad.PdfPig.Core.PdfPoint(50, 750), font);
        }
        var path = Path.Combine(_dir, name);
        File.WriteAllBytes(path, builder.Build());
        return path;
    }

    // ── PDF ───────────────────────────────────────────────────────────────

    [Fact]
    public void Pdf_Text_Is_Extracted_With_Page_Markers()
    {
        var path = WritePdf("report.pdf", "Quarterly revenue grew", "Risks and mitigations");

        var result = DocumentTextExtractor.Extract(path);

        result.Success.Should().BeTrue(result.Error);
        result.Kind.Should().Be("PDF");
        result.TotalUnits.Should().Be(2);
        result.Text.Should().Contain("Quarterly revenue grew");
        result.Text.Should().Contain("Risks and mitigations");
        // Page provenance is what lets the model cite "page 2".
        result.Text.Should().Contain("Page 1 of 2").And.Contain("Page 2 of 2");
        result.Truncated.Should().BeFalse();
    }

    [Fact]
    public void Pdf_Without_A_Text_Layer_Says_So_Instead_Of_Returning_Blank()
    {
        // A page with no text operators is what a scan looks like to a parser.
        var builder = new PdfDocumentBuilder();
        builder.AddPage(595, 842);
        var path = Path.Combine(_dir, "scan.pdf");
        File.WriteAllBytes(path, builder.Build());

        var result = DocumentTextExtractor.Extract(path);

        result.Success.Should().BeFalse();
        // The model must learn "needs OCR", not "the document is empty".
        result.Error.Should().Contain("OCR");
        result.Error.Should().Contain("scan");
    }

    [Fact]
    public void Large_Pdf_Is_Truncated_And_Reports_The_Real_Page_Total()
    {
        var pages = Enumerable.Range(1, 40)
            .Select(i => $"Page body number {i} " + new string('x', 400))
            .ToArray();
        var path = WritePdf("big.pdf", pages);

        var result = DocumentTextExtractor.Extract(path, maxChars: 2_000);

        result.Success.Should().BeTrue(result.Error);
        result.TotalUnits.Should().Be(40, "the header must state the whole document's size");
        result.UnitsIncluded.Should().BeLessThan(40);
        result.Truncated.Should().BeTrue();
        result.Text.Length.Should().BeLessThan(4_000);
    }

    // ── Word ──────────────────────────────────────────────────────────────

    [Fact]
    public async Task Docx_Headings_Paragraphs_And_Tables_Are_Extracted()
    {
        var path = Path.Combine(_dir, "summary.docx");
        var exec = new LocalDocPlanExecutor();
        await exec.ExecuteAsync(Plan("""
        {
          "format": "docx",
          "document_settings": {"language": "en"},
          "actions": [
            {"type": "add_heading", "level": 1, "text": "Quarterly Report"},
            {"type": "add_paragraph", "text": "Revenue grew steadily."},
            {"type": "add_table", "headers": ["Metric", "Value"], "rows": [["ARR", "1.2M"]]}
          ]
        }
        """), path);

        var result = DocumentTextExtractor.Extract(path);

        result.Success.Should().BeTrue(result.Error);
        result.Kind.Should().Be("Word document");
        result.Text.Should().Contain("Quarterly Report");
        result.Text.Should().Contain("Revenue grew steadily.");
        // Heading level survives as markdown so the model sees the structure.
        result.Text.Should().Contain("# Quarterly Report");
        // Table cells come through as pipe rows, not a run-on sentence.
        result.Text.Should().Contain("| Metric | Value |");
        result.Text.Should().Contain("ARR");
    }

    [Fact]
    public async Task Thai_Text_Survives_Docx_Extraction()
    {
        var path = Path.Combine(_dir, "thai.docx");
        await new LocalDocPlanExecutor().ExecuteAsync(Plan("""
        {
          "format": "docx",
          "document_settings": {"language": "th"},
          "actions": [{"type": "add_paragraph", "text": "สรุปผลประกอบการไตรมาสที่ 1"}]
        }
        """), path);

        var result = DocumentTextExtractor.Extract(path);

        result.Success.Should().BeTrue(result.Error);
        result.Text.Should().Contain("สรุปผลประกอบการไตรมาสที่ 1");
    }

    // ── Excel ─────────────────────────────────────────────────────────────

    [Fact]
    public async Task Xlsx_Sheets_Become_Labelled_Text_Tables()
    {
        var path = Path.Combine(_dir, "report.xlsx");
        await new LocalExcelPlanExecutor().ExecuteAsync(Plan("""
        {
          "operation": "create_workbook",
          "actions": [
            {"type": "create_sheet", "sheet_name": "Data"},
            {"type": "write_table", "sheet_name": "Data", "start_cell": "A1",
             "headers": ["Month", "Sales"],
             "data": [["Jan", 100], ["Feb", 250.5]]}
          ]
        }
        """), path);

        var result = DocumentTextExtractor.Extract(path);

        result.Success.Should().BeTrue(result.Error);
        result.Kind.Should().Be("Excel workbook");
        result.Text.Should().Contain("Sheet: Data");
        result.Text.Should().Contain("Month").And.Contain("Sales");
        result.Text.Should().Contain("Jan").And.Contain("Feb");
        result.Text.Should().Contain("250.5");
    }

    // ── PowerPoint ────────────────────────────────────────────────────────

    [Fact]
    public async Task Pptx_Slides_Are_Extracted_With_Slide_Numbers()
    {
        var path = Path.Combine(_dir, "deck.pptx");
        await new LocalPptxPlanExecutor().ExecuteAsync(Plan("""
        {
          "presentation_settings": {"language": "en", "title": "Deck"},
          "slides": [
            {"type": "title", "title": "Quarterly Review", "subtitle": "FY26"},
            {"type": "content", "title": "Highlights", "bullets": ["Revenue up", "Churn down"]}
          ]
        }
        """), path);

        var result = DocumentTextExtractor.Extract(path);

        result.Success.Should().BeTrue(result.Error);
        result.Kind.Should().Be("PowerPoint deck");
        result.TotalUnits.Should().Be(2);
        result.Text.Should().Contain("Slide 1 of 2");
        result.Text.Should().Contain("Quarterly Review");
        result.Text.Should().Contain("Revenue up");
    }

    // ── Plain text + rejections ───────────────────────────────────────────

    [Fact]
    public void Plain_Text_Is_Returned_Verbatim()
    {
        var path = Path.Combine(_dir, "notes.md");
        File.WriteAllText(path, "# Notes\n\nRemember the milk.", Encoding.UTF8);

        var result = DocumentTextExtractor.Extract(path);

        result.Success.Should().BeTrue(result.Error);
        result.Text.Should().Be("# Notes\n\nRemember the milk.");
    }

    [Theory]
    [InlineData("legacy.doc", ".docx")]
    [InlineData("legacy.xls", ".xlsx")]
    [InlineData("legacy.ppt", ".pptx")]
    public void Legacy_Binary_Office_Files_Fail_With_The_Fix(string name, string modern)
    {
        var path = Path.Combine(_dir, name);
        File.WriteAllBytes(path, new byte[] { 0xD0, 0xCF, 0x11, 0xE0 }); // OLE2 magic

        var result = DocumentTextExtractor.Extract(path);

        result.Success.Should().BeFalse();
        result.Error.Should().Contain(modern, "the message must name the format that works");
    }

    [Fact]
    public void A_File_Lying_About_Its_Extension_Fails_Cleanly()
    {
        var path = Path.Combine(_dir, "not-really.pdf");
        File.WriteAllText(path, "this is plain text wearing a pdf hat");

        var result = DocumentTextExtractor.Extract(path);

        result.Success.Should().BeFalse();
        result.Error.Should().Contain("not-really.pdf");
    }

    [Fact]
    public void IsSupported_Covers_The_Documented_Formats_Only()
    {
        foreach (var ok in new[] { "a.pdf", "a.docx", "a.xlsx", "a.xlsm", "a.pptx", "a.txt", "a.csv", "a.md" })
            DocumentTextExtractor.IsSupported(ok).Should().BeTrue(ok);

        foreach (var no in new[] { "a.png", "a.zip", "a.exe", "a.doc" })
            DocumentTextExtractor.IsSupported(no).Should().BeFalse(no);
    }
}
